/// Shared application state for the HTTP router.
#[derive(Clone)]
pub struct AppState {
    /// Redacted runtime configuration and immutable startup settings.
    pub config: ServerConfig,
    /// Static build metadata for the running binary.
    pub build_metadata: BuildMetadata,
    /// Stable deployment identifier loaded during startup.
    pub deployment_id: Uuid,
    /// Backing store used by the current HTTP handlers.
    pub store: Arc<dyn AppStore>,
    /// Structured audit sink for mutating and auth-related routes.
    pub audit: Arc<dyn AuditSink>,
    /// Pub/sub event system for real-time event broadcasting.
    pub pubsub: Arc<dyn PubSub>,
    /// Registry of live workspace agent connections.
    pub agent_provider: Arc<dyn AgentProvider>,
    /// Tailnet coordinator for managing agent/client connections.
    pub coordinator: Arc<dyn TailnetCoordinator>,
    /// DERP relay traffic tracker.
    pub derp_tracker: Arc<DerpTrafficTracker>,
    /// Optional Prometheus metrics handle for rendering metrics.
    pub prometheus_handle: Option<PrometheusHandle>,
    pub(crate) auth: AuthService<Arc<dyn AppStore>>,
    pub(crate) identity: IdentityService<Arc<dyn AppStore>>,
    pub(crate) deployment_stats: Arc<DeploymentStatsService<Arc<dyn AppStore>>>,
    pub(crate) health: HealthService<Arc<dyn AppStore>>,
    pub(crate) external_auth: ExternalAuthService<Arc<dyn AppStore>>,
    pub oauth2_provider: OAuth2ProviderService<Arc<dyn AppStore>>,
}

impl AppState {
    /// Builds application state with default shared clients and caches.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        config: ServerConfig,
        build_metadata: BuildMetadata,
        deployment_id: Uuid,
        store: Arc<dyn AppStore>,
        audit: Arc<dyn AuditSink>,
        pubsub: Arc<dyn PubSub>,
        agent_provider: Arc<dyn AgentProvider>,
        coordinator: Arc<dyn TailnetCoordinator>,
        derp_tracker: Arc<DerpTrafficTracker>,
        prometheus_handle: Option<PrometheusHandle>,
    ) -> Result<Self, reqwest::Error> {
        let audit = Arc::new(BatchedAuditSink::new(
            audit,
            std::time::Duration::from_millis(config.audit_batch_flush_interval_ms),
            config.audit_batch_max_size,
        )) as Arc<dyn AuditSink>;
        let auth = AuthService::with_cache_ttl(
            store.clone(),
            std::time::Duration::from_secs(config.session_cache_ttl_secs),
        );
        let identity = IdentityService::new(store.clone());
        let deployment_stats = DeploymentStatsService::new(store.clone());
        let health = HealthService::new(store.clone())?;
        let external_auth = ExternalAuthService::new(store.clone())?;
        let oauth2_provider = OAuth2ProviderService::new(store.clone());

        Ok(Self {
            config,
            build_metadata,
            deployment_id,
            store,
            audit,
            pubsub,
            agent_provider,
            coordinator,
            derp_tracker,
            prometheus_handle,
            auth,
            identity,
            deployment_stats,
            health,
            external_auth,
            oauth2_provider,
        })
    }

    /// Cancels the background deployment-stats refresh loop.
    ///
    /// This should be called during the graceful shutdown sequence before
    /// closing the database pool, so the loop does not attempt further
    /// queries after the pool is closed.
    pub fn close_deployment_stats(&self) {
        self.deployment_stats.close();
    }
}

