        async fn soft_delete_user(&self, user_id: Uuid) -> Result<bool, StorageError> {
            let mut users = self
                .users
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;
            let Some(user) = users.get_mut(&user_id) else {
                return Ok(false);
            };
            if user.deleted {
                return Ok(false);
            }
            user.deleted = true;
            user.status = UserStatus::Suspended;
            user.updated_at = OffsetDateTime::now_utc();
            drop(users);

            self.sessions
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .retain(|_, user| user.id != user_id);
            self.api_keys
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .retain(|_, key| key.user_id != user_id);
            self.organization_members
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .retain(|(_, member_user_id), _| member_user_id != &user_id);
            self.password_hashes
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .remove(&user_id);
            self.one_time_passcodes
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .remove(&user_id);
            self.appearance
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .remove(&user_id);
            self.preferences
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .remove(&user_id);

            Ok(true)
        }

        async fn list_user_memberships(
            &self,
            user_id: Uuid,
        ) -> Result<Vec<OrganizationMemberRecord>, StorageError> {
            let members = self
                .organization_members
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;
            let mut rows = members
                .values()
                .filter(|member| member.user_id == user_id)
                .cloned()
                .collect::<Vec<_>>();
            rows.sort_by(|left, right| left.organization_id.cmp(&right.organization_id));
            Ok(rows)
        }

        async fn update_user_roles(
            &self,
            user_id: Uuid,
            roles: Vec<String>,
        ) -> Result<Option<UserRecord>, StorageError> {
            let now = OffsetDateTime::now_utc();
            let mut users = self
                .users
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;
            let Some(user) = users.get_mut(&user_id) else {
                return Ok(None);
            };
            if user.deleted {
                return Ok(None);
            }
            let slim_roles = roles
                .iter()
                .map(|role| SlimRoleRecord {
                    name: role.clone(),
                    display_name: role
                        .split('-')
                        .map(|part| {
                            let mut chars = part.chars();
                            match chars.next() {
                                Some(first) => {
                                    first.to_uppercase().collect::<String>() + chars.as_str()
                                }
                                None => String::new(),
                            }
                        })
                        .collect::<Vec<_>>()
                        .join(" "),
                    organization_id: None,
                })
                .collect::<Vec<_>>();
            user.roles = slim_roles.clone();
            user.updated_at = now;
            let updated_user = user.clone();
            drop(users);

            self.organization_members
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .values_mut()
                .filter(|member| member.user_id == user_id)
                .for_each(|member| {
                    member.global_roles = slim_roles.clone();
                });

            Ok(Some(updated_user))
        }

        async fn update_user_profile(
            &self,
            user_id: Uuid,
            username: &str,
            name: &str,
        ) -> Result<Option<UserRecord>, StorageError> {
            let mut users = self
                .users
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;
            let Some(user) = users.get_mut(&user_id) else {
                return Ok(None);
            };
            if user.deleted {
                return Ok(None);
            }
            user.username = username.to_owned();
            user.name = name.to_owned();
            user.updated_at = OffsetDateTime::now_utc();
            let updated_user = user.clone();
            drop(users);

            self.organization_members
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .values_mut()
                .filter(|member| member.user_id == user_id)
                .for_each(|member| {
                    member.username = username.to_owned();
                    member.name = name.to_owned();
                    member.updated_at = updated_user.updated_at;
                });

            Ok(Some(updated_user))
        }

