        async fn cancel_template_provisioner_job(
            &self,
            job_id: Uuid,
        ) -> Result<bool, StorageError> {
            let mut jobs = self
                .provisioner_jobs
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            match jobs.get_mut(&job_id) {
                Some(j) if j.canceled_at.is_none() && j.completed_at.is_none() => {
                    let now = OffsetDateTime::now_utc();
                    j.canceled_at = Some(now);
                    // Only complete immediately if no worker has picked up the job
                    // (matches Go semantics: !job.WorkerID.Valid)
                    if j.worker_id.is_none() {
                        j.completed_at = Some(now);
                        j.job_status = "canceled".to_owned();
                    } else {
                        j.job_status = "canceling".to_owned();
                    }
                    j.updated_at = now;
                    Ok(true)
                }
                _ => Ok(false),
            }
        }

        async fn insert_file(
            &self,
            input: InsertFileInput,
        ) -> Result<InsertFileResult, StorageError> {
            let mut files = self
                .files
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;

            // Mimic ON CONFLICT (hash, created_by) DO UPDATE SET id = files.id
            // – return the existing record’s id when a duplicate exists.
            if let Some(existing) = files
                .values()
                .find(|f| f.hash == input.hash && f.created_by == input.created_by)
            {
                return Ok(InsertFileResult { id: existing.id });
            }

            let id = input.id;
            let record = FileRecord {
                id,
                hash: input.hash,
                created_by: input.created_by,
                created_at: OffsetDateTime::now_utc(),
                mimetype: input.mimetype,
                data: input.data,
            };
            files.insert(record.id, record);
            Ok(InsertFileResult { id })
        }

