        async fn acquire_pending_notification_messages(
            &self,
            limit: u32,
            max_attempt_count: u32,
        ) -> Result<Vec<NotificationMessageRecord>, StorageError> {
            let messages = self
                .notification_messages
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            Ok(messages
                .iter()
                .filter(|m| {
                    m.status == NotificationMessageStatus::Pending
                        && (m.attempt_count as u32) < max_attempt_count
                })
                .take(limit as usize)
                .cloned()
                .collect())
        }

        async fn update_notification_message_status(
            &self,
            message_id: Uuid,
            status: NotificationMessageStatus,
        ) -> Result<bool, StorageError> {
            let mut messages = self
                .notification_messages
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            if let Some(msg) = messages.iter_mut().find(|m| m.id == message_id) {
                msg.status = status;
                msg.updated_at = OffsetDateTime::now_utc();
                Ok(true)
            } else {
                Ok(false)
            }
        }

        async fn increment_notification_message_attempt_count(
            &self,
            message_id: Uuid,
        ) -> Result<bool, StorageError> {
            let mut messages = self
                .notification_messages
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            if let Some(msg) = messages.iter_mut().find(|m| m.id == message_id) {
                msg.attempt_count += 1;
                msg.updated_at = OffsetDateTime::now_utc();
                Ok(true)
            } else {
                Ok(false)
            }
        }

        // -----------------------------------------------------------------
        // Groups
        // -----------------------------------------------------------------

        async fn create_group(
            &self,
            input: &CreateGroupInput,
        ) -> Result<GroupRecord, StorageError> {
            let mut groups = self
                .groups
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            // Check for duplicate name within the organization.
            let duplicate = groups
                .values()
                .any(|g| g.organization_id == input.organization_id && g.name == input.name);
            if duplicate {
                return Err(StorageError::invalid_data(
                    "group with this name already exists in the organization",
                ));
            }
            let id = Uuid::new_v4();
            let now = OffsetDateTime::now_utc();
            let record = GroupRecord {
                id,
                name: input.name.clone(),
                display_name: input.display_name.clone(),
                organization_id: input.organization_id,
                avatar_url: input.avatar_url.clone(),
                quota_allowance: input.quota_allowance,
                source: "user".to_owned(),
                created_at: now,
            };
            groups.insert(id, record.clone());
            Ok(record)
        }

        async fn find_group_by_id(
            &self,
            group_id: Uuid,
        ) -> Result<Option<GroupRecord>, StorageError> {
            Ok(self
                .groups
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?
                .get(&group_id)
                .cloned())
        }

        async fn delete_group(&self, group_id: Uuid) -> Result<bool, StorageError> {
            let removed = self
                .groups
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?
                .remove(&group_id)
                .is_some();
            if removed {
                // Also remove all members of this group.
                self.group_members
                    .lock()
                    .map_err(|e| StorageError::unavailable(e.to_string()))?
                    .retain(|m| m.group_id != group_id);
            }
            Ok(removed)
        }

        async fn list_groups(
            &self,
            organization_id: Uuid,
        ) -> Result<Vec<GroupRecord>, StorageError> {
            let groups = self
                .groups
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            let mut result: Vec<GroupRecord> = groups
                .values()
                .filter(|g| g.organization_id == organization_id)
                .cloned()
                .collect();
            result.sort_by(|a, b| a.name.to_lowercase().cmp(&b.name.to_lowercase()));
            Ok(result)
        }

        async fn insert_group_member(
            &self,
            group_id: Uuid,
            user_id: Uuid,
        ) -> Result<(), StorageError> {
            // Validate that the group exists (mirrors FK constraint in PostgresStore).
            {
                let groups = self
                    .groups
                    .lock()
                    .map_err(|e| StorageError::unavailable(e.to_string()))?;
                if !groups.contains_key(&group_id) {
                    return Err(StorageError::invalid_data("group not found"));
                }
            }
            let mut members = self
                .group_members
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            let already_exists = members
                .iter()
                .any(|m| m.group_id == group_id && m.user_id == user_id);
            if already_exists {
                return Err(StorageError::invalid_data(
                    "user is already a member of this group",
                ));
            }
            members.push(GroupMemberRecord { group_id, user_id });
            Ok(())
        }

        async fn delete_group_member(
            &self,
            group_id: Uuid,
            user_id: Uuid,
        ) -> Result<bool, StorageError> {
            let mut members = self
                .group_members
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            let before = members.len();
            members.retain(|m| !(m.group_id == group_id && m.user_id == user_id));
            Ok(members.len() < before)
        }

        async fn list_group_members(
            &self,
            group_id: Uuid,
        ) -> Result<Vec<GroupMemberRecord>, StorageError> {
            let members = self
                .group_members
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            let users = self
                .users
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            // PostgresStore JOINs on users, filters u.deleted = false,
            // and sorts by LOWER(u.username) ASC.
            let mut result: Vec<GroupMemberRecord> = members
                .iter()
                .filter(|m| m.group_id == group_id)
                .filter(|m| users.get(&m.user_id).is_some_and(|u| !u.deleted))
                .cloned()
                .collect();
            result.sort_by(|a, b| {
                let a_name = users
                    .get(&a.user_id)
                    .map(|u| u.username.to_lowercase())
                    .unwrap_or_default();
                let b_name = users
                    .get(&b.user_id)
                    .map(|u| u.username.to_lowercase())
                    .unwrap_or_default();
                a_name.cmp(&b_name)
            });
            Ok(result)
        }

