    #[tokio::test]
    async fn chat_git_watch_requires_websocket_upgrade() -> Result<(), Box<dyn Error>> {
        let app = build_router(test_state(true)?, None);
        let session_token = create_and_login(&app).await?;

        // Create a chat
        let create_response = call(
            app.clone(),
            authenticated_json_request(
                Method::POST,
                "/api/v2/chats",
                &session_token,
                &CreateChatRequest {
                    content: vec![],
                    workspace_id: None,
                    model_config_id: None,
                },
            )?,
        )
        .await?;
        let body = to_bytes(create_response.into_body(), 1_000_000).await?;
        let chat_with_messages: Value = serde_json::from_slice(&body)?;
        let chat_id = chat_with_messages["chat"]["id"]
            .as_str()
            .ok_or("missing chat id")?;

        // Without WebSocket upgrade headers the extractor rejects with 400.
        let watch_response = call(
            app,
            authenticated_request(
                Method::GET,
                &format!("/api/v2/chats/{chat_id}/git/watch"),
                &session_token,
            )?,
        )
        .await?;
        assert_eq!(watch_response.status(), StatusCode::BAD_REQUEST);
        Ok(())
    }

    #[tokio::test]
    async fn chat_git_watch_requires_auth() -> Result<(), Box<dyn Error>> {
        let app = build_router(test_state(true)?, None);
        let fake_id = Uuid::new_v4();

        // Without WS upgrade headers the WebSocketUpgrade extractor rejects
        // with 400 before auth runs.  With WS headers, auth rejects with 401.
        let response = call(
            app,
            request(Method::GET, &format!("/api/v2/chats/{fake_id}/git/watch"))?,
        )
        .await?;
        assert!(
            response.status() == StatusCode::UNAUTHORIZED
                || response.status() == StatusCode::BAD_REQUEST,
            "expected 401 or 400, got {}",
            response.status(),
        );
        Ok(())
    }

